export class GeoIPDataService {
  private static instance: GeoIPDataService;

  public static getInstance(): GeoIPDataService {
    if (!GeoIPDataService.instance) {
      GeoIPDataService.instance = new GeoIPDataService();
    }
    return GeoIPDataService.instance;
  }

  public getCountryName(code: string): string {
    return COUNTRY_NAMES[code.toUpperCase()] || code.toUpperCase();
  }

  public getAllCountryCodes(): string[] {
    return Object.keys(COUNTRY_NAMES);
  }

  public getIPsForCountry(code: string): string[] {
    const upper = code.toUpperCase();
    if (REPRESENTATIVE_IPS[upper]) {
      return REPRESENTATIVE_IPS[upper];
    }
    const c1 = upper.charCodeAt(0) || 65;
    const c2 = upper.charCodeAt(1) || 65;
    return [`45.${c1 % 200}.${c2 % 200}.1`];
  }

  public getUdpTargetsForRegion(regionCodes: string[], port: number = 9999): GeoIpTarget[] {
    const isGlobal = regionCodes.includes("ALL") || regionCodes.includes("global");
    const targetCodes = isGlobal ? this.getAllCountryCodes() : regionCodes;
    const results: GeoIpTarget[] = [];

    for (const code of targetCodes) {
      const upper = code.toUpperCase().trim();
      if (!upper || upper === "ALL" || upper === "GLOBAL") continue;
      const countryName = this.getCountryName(upper);
      const ips = this.getIPsForCountry(upper);
      if (ips && ips.length > 0) {
        const host = ips[0];
        results.push({
          transport: "udp",
          host,
          port,
          countryCode: upper,
          countryName,
          nodeId: `${countryName} (${upper})`,
          endpointId: `${countryName} (${upper})`,
        });
      }
    }
    return results;
  }
}
